  list-style: none;
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

a:hover, a:focus {
  text-decoration: underline;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link {
  position: absolute;
  top: -100px;
  left: 0;
  background: var(--color-primary);
  color: #000;
  padding: 1rem;
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
}

.container {
  max-width: var(--container-max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Header */
header {
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  background: var(--color-bg);
  position: sticky;
  top: 0;
  z-index: 50;
}

header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-md);
}

.logo {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--color-text);
}

nav[aria-label="Primary"] ul {
  display: flex;
  gap: var(--spacing-lg);
}

.header-actions {
  display: flex;
  gap: var(--spacing-md);
  align-items: center;
}

.search-form {
  display: flex;
}

.search-input {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  color: var(--color-text);
  padding: 0.5rem;
  border-radius: 4px 0 0 4px;
}

.search-button {
  background: var(--color-primary);
  color: #000;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 0 4px 4px 0;
  cursor: pointer;
}

/* Main content */
main {
  outline: none;
}

section {
  padding: var(--spacing-xl) 0;
}

h1, h2, h3 {
  margin-bottom: var(--spacing-md);
}

h2 {
  font-size: 2rem;
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

/* Hero Section */
.hero {
  background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=1200') center/cover no-repeat;
  min-height: 60vh;
  display: flex;
  align-items: center;
  text-align: center;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 {
  font-size: 3.5rem;
  font-weight: 800;
  line-height: 1.1;
}

.hero p {
  font-size: 1.25rem;
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-lg);
}

.btn {
  display: inline-block;
  background: var(--color-primary);
  color: #000;
  padding: 1rem 2rem;
  border-radius: 4px;
  font-weight: bold;
  border: none;
  cursor: pointer;
  font-size: 1rem;
}

.btn:hover, .btn:focus {
  background: #d1a5ff;
  text-decoration: none;
}

/* Product Grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: var(--spacing-lg);
}

.product-card {
  background: var(--color-surface);
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.2s, background-color 0.2s;
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  background-color: var(--color-surface-hover);
  transform: translateY(-4px);
}

.product-image {
  aspect-ratio: 1;
  background: #333;
  object-fit: cover;
}

.product-info {
  padding: var(--spacing-md);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.product-title {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-xs);
}

.product-title a {
  color: var(--color-text);
}

.product-price {
  font-weight: bold;
  color: var(--color-secondary);
  margin-bottom: var(--spacing-md);
}

.btn-add {
  margin-top: auto;
  width: 100%;
  padding: 0.75rem;
  background: transparent;
  border: 1px solid var(--color-primary);
  color: var(--color-primary);
}

.btn-add:hover, .btn-add:focus {
  background: var(--color-primary);
  color: #000;
}

/* Deals Section */
.deals-banner {
  background: var(--color-surface);
  border-radius: 12px;
  padding: var(--spacing-xl);
  display: flex;
  align-items: center;
  gap: var(--spacing-xl);
  border: 1px solid var(--color-border);
}

.deals-text {
  flex: 1;
}

.deals-text h3 {
  font-size: 2.5rem;
  color: var(--color-secondary);
}

/* Footer */
footer {
  background: var(--color-surface);
  padding: var(--spacing-xl) 0;
  border-top: 1px solid var(--color-border);
  margin-top: var(--spacing-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
}

.footer-section h4 {
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.footer-section ul li {
  margin-bottom: var(--spacing-sm);
}

.footer-section a {
  color: var(--color-text-muted);
}

.footer-section a:hover {
  color: var(--color-primary);
}

.footer-bottom {
  margin-top: var(--spacing-xl);
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-border);
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.875rem;
}

/* Focus styles */
:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 4px;
}

/* Mobile Menu Toggle (Simplified) */
.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--color-text);
  font-size: 1.5rem;
  cursor: pointer;
}

@media (max-width: 768px) {
  .menu-toggle {
    display: block;
  }

  nav[aria-label="Primary"] {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    width: 100%;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-md);
  }

  nav[aria-label="Primary"].active {
    display: block;
  }

  nav[aria-label="Primary"] ul {
    flex-direction: column;
    gap: var(--spacing-md);
  }

  .hero h1 {
    font-size: 2.5rem;
  }

  .deals-banner {
    flex-direction: column;
    text-align: center;
    padding: var(--spacing-lg);
  }
}

@media (forced-colors: active) {
  .btn, .btn-add, .search-button {
    border: 1px solid ButtonBorder;
  }
  .product-card {
    border: 1px solid CanvasText;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
